import pytest

from tools.check_comments import comment_violations


@pytest.mark.parametrize(
    "source",
    [
        "value = 1\n",
        "value = 1  # noqa: PLR2004\n",
        "value = 1  # type: ignore[assignment]\n",
        "#!/usr/bin/env python\nvalue = 1\n",
        "# Generated by Django 6.1 on 2026-11-17\nvalue = 1\n",
        "text = '# not a comment'\n",
    ],
)
def test_allowed_sources_have_no_violation(source: str) -> None:
    assert list(comment_violations(source)) == []


@pytest.mark.parametrize(
    ("source", "line_number"),
    [
        ("# explains something\nvalue = 1\n", 1),
        ("value = 1  # because reasons\n", 1),
        ("value = 1\n# type: ignore\n", 2),
        ("value = 1\n#!/not/first/line\n", 2),
    ],
)
def test_explanatory_comments_are_reported(source: str, line_number: int) -> None:
    assert [found for found, _ in comment_violations(source)] == [line_number]
